/* The shared library's symbol versions (ELF): every public function of
 * noqtis.h at the one node NOQTIS_0, the ABI of major version 0; nothing
 * else is exported (the pattern nq* matches only what NQAPI leaves
 * visible: the rest is built with hidden visibility). Functions added in
 * 0.x releases join that node too; there is no node per release, so a
 * program's version reference names NOQTIS_0, not the release it needs. */
NOQTIS_0 {
  global:
    nq*;
  local:
    *;
};
